"""Differential file programs generated by the BBC I/O frontend experiment."""
from pathlib import Path
import importlib.util,json,subprocess,sys
TASK=Path(__file__).resolve().parent;ROOT=TASK.parents[2]
def module(n,p):
 s=importlib.util.spec_from_file_location(n,p);m=importlib.util.module_from_spec(s);s.loader.exec_module(m);return m
def programs():
 p=module('proc_io',ROOT/'docs/tasks/C004/tools/test_procedures.py')
 seed=['h%=OPENOUT("file.dat"):BPUT#h%,0:BPUT#h%,127:BPUT#h%,128:BPUT#h%,255:CLOSE#h%']
 read=['h%=OPENIN("file.dat"):PRINT ;h%>0;":";EOF#h%', 'WHILE NOT EOF#h%:PRINT ;BGET#h%;",";:ENDWHILE:PRINT:PRINT ;EOF#h%:CLOSE#h%']
 pairs=[
 (seed+read,[]),
 (['h%=OPENOUT("file.dat"):BPUT#h%,CHR$(0)+CHR$(128)+CHR$(255)',
   'BPUT#h%,"";:BPUT#h%,"":BPUT#h%,STRING$(255,"q");:CLOSE#h%']+read,[]),
 (['PRINT ;OPENIN("io-impossible-no-file.dat");":";OPENUP("io-impossible-no-file.dat")'],[]),
 (['h%=OPENOUT("file.dat"):CLOSE#h%:h%=OPENIN("file.dat"):PRINT ;EOF#h%;":";BGET#h%:CLOSE#h%'],[]),
 (seed+['h%=OPENOUT("file.dat"):BPUT#h%,65:CLOSE#h%']+read,[]),
 (seed+['h%=OPENUP("file.dat"):BPUT#h%,42:CLOSE#h%']+read,[]),
 (seed+['h%=OPENIN("file.dat"):BPUT#h%,42:CLOSE#h%']+read,[]),
 (seed+['h%=OPENIN("file.dat"):PRINT ;BGET#(h%+256);":";EOF#(h%+256):CLOSE#(h%+256)',
        'PRINT ;BGET#0;":";EOF#0;":";BGET#255;":";EOF#255'],[]),
 (seed+['h%=OPENIN("file.dat"):FOR i%=1 TO 4:v%=BGET#h%:NEXT',
        'PRINT ;BGET#h%;":";BGET#h%;":";EOF#h%:CLOSE#h%'],[]),
 (seed+['DIM f%(8):FOR i%=0 TO 8:f%(i%)=OPENIN("file.dat"):PRINT ;f%(i%);",";:NEXT:PRINT',
        'CLOSE#255:h%=OPENIN("file.dat"):PRINT ;h%:CLOSE#0'],[]),
 (seed+['h%=OPENIN("file.dat"+CHR$(0)+"ignored"):PRINT ;h%>0:CLOSE#h%',
        'h%=OPENIN("file.dat"+CHR$(13)+"ignored"):PRINT ;h%>0:CLOSE#h%'],[]),
 (seed+['PRINT ;OPENIN(STRING$(255,"q"))'],[]),
 (seed+['h%=OPENIN("file.dat"):PRINT ;BGET#h%+BGET#h%;":";BGET#h%+BGET#h%:CLOSE#h%'],[]),
 (seed+['h%=OPENIN("file.dat"):PRINT ;100+BGET#FNgethandle;":";h%:CLOSE#h%'],['DEF FNgethandle=h%']),
 (['h%=OPENOUT("file.dat"):old%=h%:BPUT#h%,FNputbyte:CLOSE#old%']+read,
  ['DEF FNputbyte:h%=0:=257']),
 (['h%=OPENOUT("file.dat"):old%=h%:BPUT#h%,FNputstr;:CLOSE#old%']+read,
  ['DEF FNputstr:h%=0:=CHR$(0)+CHR$(128)+CHR$(255)']),
 (seed+['scratch$="file.datX":h%=OPENIN(FNfilename+""):PRINT ;h%>0:CLOSE#h%'],['DEF FNfilename="file.dat"']),
 (seed+['f$=FNfilename:h%=OPENIN f$:PRINT ;h%>0:CLOSE#h%'],['DEF FNfilename="file.dat"']),
 (['h%=OPENOUT("file.dat"):BPUT#h%,-0.9:BPUT#h%,-1:BPUT#h%,256.9:CLOSE#h%']+read,[]),
 (seed+['PRINT ;BGET#(256.9);":";EOF#(256.9):CLOSE#-1'],[]),
 ]
 out=[p.program(a,b) for a,b in pairs]
 for body in [['PRINT BGET#1E20'],['PRINT EOF#1E20'],['CLOSE#1E20'],['h%=OPENOUT("file.dat"):BPUT#h%,1E20']]:
  c=p.program(body,[]);c.update(reference_error=True,status=1);out.append(c)
 out += [dict(source=a,diagnostic=b) for a,b in [
  ('h%=OPENIN FNfile\nEND\nDEF FNfile="file.dat"\n','Direct FN filename carriers are unqualified'),
  ('INPUT a%\n','Only INPUT LINE is supported'),
  ('INPUT LINE a%\n','INPUT LINE requires one scalar string variable'),
  ('INPUT LINE "p";a$\n','Expected a name'),
  ('INPUT LINE a$,b$\n','INPUT LINE separators and multiple targets are unsupported'),
  ('BPUT#1,2;\n','Unexpected text after statement'),
 ]]
 return out

def main():
 h=module('output_io',ROOT/'docs/tasks/C002/tools/test_output.py');h.TASK=TASK
 smoke='--smoke' in sys.argv
 if smoke:sys.argv.remove('--smoke')
 h.programs=(lambda:programs()[:2]) if smoke else programs
 sys.argv += ['--isolate-reference','--skip-legacy']
 if '--string-runtime' not in sys.argv:sys.argv+=['--string-runtime',str(ROOT/'compiler/build/string-runtime')]
 h.main()
 b=TASK/'build/output-integration';rt=TASK/'build/io-runtime';template=(rt/'runtime-0.bin').read_bytes();rows=[]
 for i,c in enumerate(json.loads((b/'cases.json').read_text())):
  if 'diagnostic' in c:continue
  data=(ROOT/'.emulator/sdcard'/f'p{i}.bin').read_bytes();pos=data.find(template[:12])
  if pos<0:continue
  base=0x40000+pos;out=b/f'io-{base:x}.dat'
  subprocess.run(['/Agon/agondev/release/bin/ez80-none-elf-ld',f'-Ttext=0x{base:x}','-e','io_open','--oformat=binary','-o',str(out),str(rt/'runtime.o')],check=True)
  assert data[pos:pos+len(template)]==out.read_bytes();rows.append(dict(program=i,base=base,bytes=len(template)))
 assert rows;(b/'io-links.json').write_text(json.dumps(rows,indent=2)+'\n');print('Independent I/O links:',rows)
if __name__=='__main__':main()
